<?php require __DIR__.'/_guard.php';$rows=$conn->query("SELECT h.*,p.product_name,u.full_name FROM stock_history h JOIN products p ON p.id=h.product_id JOIN users u ON u.id=h.user_id ORDER BY h.id DESC LIMIT 300");?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stock History</title><link rel="stylesheet" href="../assets/css/modern.css"></head><body><main class="page"><header class="topbar"><div><a class="brand" href="dashboard.php">Fresh<span>Mart</span></a><h1>Stock history</h1><p class="muted">Audit trail of stock received and issued.</p></div><a class="btn" href="dashboard.php">Dashboard</a></header><nav class="nav"><a href="dashboard.php">Overview</a><a href="stock.php">Stock In / Out</a><a href="history.php">Stock history</a><a href="low_stock.php">Low stock</a></nav><section class="panel table-wrap"><table><thead><tr><th>Product</th><th>Staff</th><th>Action</th><th>Quantity</th><th>Previous</th><th>New</th><th>Date</th></tr></thead><tbody><?php if($rows&&$rows->num_rows):while($r=$rows->fetch_assoc()):?><tr><td><?=htmlspecialchars($r['product_name'])?></td><td><?=htmlspecialchars($r['full_name'])?></td><td><span class="badge"><?=strtoupper($r['action'])?></span></td><td><?=$r['quantity']?></td><td><?=$r['previous_quantity']?></td><td><?=$r['new_quantity']?></td><td><?=htmlspecialchars($r['created_at'])?></td></tr><?php endwhile;else:?><tr><td colspan="7">No stock history found.</td></tr><?php endif;?></tbody></table></section></main></body></html>
